INSERT INTO `roles` (`id`,`name`,`description`,`is_admin`,`is_system`,`all_sites`,`created_at`,`updated_at`,`coop_cash_account_id`) VALUES
(1,'Company Administrator','Everything in every module of the company, including user accounts, roles, page access, the closing date, the ISP set-up and the audit trail.',1,1,1,'2026-11-02 00:20:29',NULL,NULL),
(2,'Accountant','Chart of Accounts, Fixed Assets, Banking and reconciliation, the BIR Reports and Withholding Tax Table, all module reports, and the financial statements.',0,1,1,'2026-11-02 00:20:29',NULL,NULL),
(3,'A/R Clerk','Customers module transactions and the Customer and Receivables reports.',0,1,1,'2026-11-02 00:20:29',NULL,NULL),
(4,'A/P Clerk','Vendors module transactions, Pay Bills, advances to suppliers, the Vendors and Payables reports, and BIR Form 2307 for suppliers.',0,1,1,'2026-11-02 00:20:29',NULL,NULL),
(5,'Inventory Clerk','Items, sites, receiving, adjustments, assembly builds, disassembly and processing orders, stock counts, and inventory quantity reports.',0,1,1,'2026-11-02 00:20:29',NULL,NULL),
(6,'Sales Representative','Estimates, sales orders, and invoices, and the Sales reports.',0,1,1,'2026-11-02 00:20:29',NULL,NULL),
(7,'Cashier','Collects subscriber payments in an open cashier shift, prints collection receipts, counts the cash at the end of the shift; also the POS register at the assigned terminal.',0,1,0,'2026-11-02 00:20:29','2026-11-02 00:20:30',NULL),
(8,'POS Supervisor','Everything a cashier can do, plus approving voids, refunds, price overrides, and large discounts, and running X- and Z-readings.',0,1,1,'2026-11-02 00:20:29',NULL,NULL),
(9,'Auditor','View-only access to all transactions, reports, and the audit trail. Cannot create or change anything.',0,1,1,'2026-11-02 00:20:29',NULL,NULL),
(10,'General Manager','Opens every cooperative, savings, loan, teller, distribution and compliance page, approves loans and transactions, and sees every report.',0,1,1,'2026-11-02 00:20:30',NULL,NULL),
(11,'Bookkeeper','Records cooperative vouchers, posts interest and penalties, runs the subsidiary ledgers and financial reports.',0,1,1,'2026-11-02 00:20:30',NULL,NULL),
(12,'Loan Officer','Loan applications, credit investigation, loan release, collection, loan accounts and loan reports.',0,1,1,'2026-11-02 00:20:30',NULL,NULL),
(13,'Credit Committee','Reviews and approves loan applications and waivers; views loan reports.',0,1,1,'2026-11-02 00:20:30',NULL,NULL),
(14,'Teller','Teller shift, official receipts, savings deposits and withdrawals, loan collection and passbook printing.',0,1,1,'2026-11-02 00:20:30',NULL,NULL),
(15,'Membership Officer','Member records, member statements, savings account opening and the member reports.',0,1,1,'2026-11-02 00:20:30',NULL,NULL),
(16,'Collector','Loan collection and the collection, due and aging reports.',0,1,1,'2026-11-02 00:20:30',NULL,NULL),
(17,'Branch Manager','Everything of the branch: approves savings accounts, withdrawals, loans and waivers, closes teller shifts, and sees the branch reports.',0,1,1,'2026-11-02 00:20:30',NULL,NULL),
(18,'Billing Officer','Billing runs (preview and generation), invoices, adjustments to request, statements of account, disputes and payment arrangements to record, and the billing reports.',0,1,1,'2026-11-02 00:20:30',NULL,NULL),
(19,'Collection Officer','Follows up overdue subscribers: verifies bank / e-wallet payment references, records field collections, payment arrangements and collection notes; sees the aging, delinquency and disconnection lists.',0,1,1,'2026-11-02 00:20:30',NULL,NULL),
(20,'Network Administrator','Network devices and integrations (MikroTik, RADIUS, OLT, TR-069), provisioning, the network operations queue and retries, disconnections and reconnections, infrastructure and the network map, outages.',0,1,1,'2026-11-02 00:20:30',NULL,NULL),
(21,'Technical Supervisor','Dispatches and verifies work orders, assigns technicians, approves installations and equipment replacements, manages tickets, outages and the field reports.',0,1,1,'2026-11-02 00:20:30',NULL,NULL),
(22,'Installation Technician','Field installer: own task list, accepts and completes installation work orders, records materials used, serial numbers, signal readings, photos and the subscriber acceptance. No billing or financial pages.',0,1,1,'2026-11-02 00:20:30',NULL,NULL),
(23,'Maintenance Technician','Field repairs: own task list, repair, relocation, recovery and replacement work orders and the tickets assigned, materials used and returned. No billing or financial pages.',0,1,1,'2026-11-02 00:20:30',NULL,NULL),
(24,'Customer Service Representative','Front desk and hotline: subscriber look-up, applications, support tickets, service requests, statements of account, announcements; no collections, adjustments or network commands.',0,1,1,'2026-11-02 00:20:30',NULL,NULL),
(25,'Inventory Custodian','The network stockroom: equipment and material items, receiving, transfers to technicians, returns, damaged stock, counts, serial numbers and the inventory reports.',0,1,1,'2026-11-02 00:20:30',NULL,NULL),
(26,'Sales Agent','Signs up subscribers: new applications (own), checks coverage and plans, follows the status of the applications and sees own commissions.',0,1,1,'2026-11-02 00:20:30',NULL,NULL);
