INSERT INTO `isp_contract_templates` (`id`,`name`,`body`,`is_default`,`is_active`,`created_at`) VALUES
(1,'Standard Residential / Business Subscription Agreement','SUBSCRIPTION AGREEMENT\n\nThis agreement is made on {date} between {company}, {company_address} (the Provider), and {name}, {address} (the Subscriber), for account {account_no}.\n\n1. Service. The Provider supplies the {plan} plan: up to {download} Mbps download and {upload} Mbps upload, {fair_use}. Speeds are best effort and depend on the line and the devices used.\n2. Fees. The monthly fee is {monthly_fee}{vat_note}, billed {billing}, due {due_days} days after the invoice date. Installation fee {installation_fee}; security deposit {deposit}.\n3. Term. The agreement starts on {start_date} for {months} months{lock_in}. An early termination during the lock-in period is charged {etf}.\n4. Late payment. An unpaid bill {grace_days} days after its due date may lead to disconnection after a final notice. A reconnection fee of {reconnection_fee} may apply.\n5. Equipment. Equipment lent or rented to the Subscriber remains the Provider\'s property and is returned when the service ends; lost or damaged equipment is charged at cost, less the deposit.\n6. Interruptions. Outages beyond {sla_hours} hours caused by the Provider\'s network are credited in proportion to the downtime, upon verification.\n7. Privacy. {privacy}\n8. Complaints. Complaints may be filed at any office or through the customer portal, and with the National Telecommunications Commission.\n\nAccepted by the Subscriber: ______________________   Date: __________\nFor the Provider: ______________________',1,1,'2026-11-02 00:20:30');
INSERT INTO `isp_contracts` (`id`,`contract_no`,`account_id`,`template_id`,`plan_id`,`start_date`,`end_date`,`lock_in_months`,`early_termination_fee`,`body_snapshot`,`accepted_at`,`accepted_name`,`accepted_ip`,`status`,`amends_id`,`terminated_at`,`notes`,`created_by`,`created_at`) VALUES
(1,'CT-000001',1,1,2,'2026-05-03','2027-05-02',12,'3500.00','SUBSCRIPTION AGREEMENT\n\nThis agreement is made on 05/03/2026 between Sample Trading Company, 123 Rizal Avenue, Makati City, Metro Manila (the Provider), and Maria Santos, 3 Rizal St., Brgy. Atlag, City of Malolos, Bulacan (the Subscriber), for account 1000001.\n\n1. Service. The Provider supplies the Fiber 50 Mbps plan: up to 50 Mbps download and 50 Mbps upload, no data cap. Speeds are best effort and depend on the line and the devices used.\n2. Fees. The monthly fee is 1,249.00 (VAT inclusive), billed monthly in advance, due 15 days after the invoice date. Installation fee 1,500.00; security deposit 0.00.\n3. Term. The agreement starts on 05/03/2026 for 12 months, with a lock-in period of 12 months. An early termination during the lock-in period is charged 3,500.00.\n4. Late payment. An unpaid bill 5 days after its due date may lead to disconnection after a final notice. A reconnection fee of 300.00 may apply.\n5. Equipment. Equipment lent or rented to the Subscriber remains the Provider\'s property and is returned when the service ends; lost or damaged equipment is charged at cost, less the deposit.\n6. Interruptions. Outages beyond 24 hours caused by the Provider\'s network are credited in proportion to the downtime, upon verification.\n7. Privacy. Your personal data is processed by the cooperative for your subscription, billing and service support only, as allowed by the Data Privacy Act of 2012 (RA 10173).\n8. Complaints. Complaints may be filed at any office or through the customer portal, and with the National Telecommunications Commission.\n\nAccepted by the Subscriber: ______________________   Date: __________\nFor the Provider: ______________________','2026-04-28 09:30:01','Maria Santos',NULL,'active',NULL,NULL,NULL,27,'2026-05-03 13:00:00'),
