(1,'billing','Daily invoice generation','Generates (and, when runs need no approval, posts) the invoices of accounts due today',1440,1,1,3,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-02 00:20:30'),
(2,'due_check','Billing due-date checks','Marks unpaid invoices overdue after their due date',60,NULL,1,3,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-02 00:20:30'),
(3,'late_fees','Late-charge assessment','Charges the plan late fee once per overdue invoice',1440,2,1,3,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-02 00:20:30'),
(4,'reminders','Payment reminders','Due-date reminders before the due date and overdue reminders after it',1440,8,1,3,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-02 00:20:30'),
(5,'disc_eval','Disconnection eligibility evaluation','Builds the disconnection queue from the rules and sends the final notices',120,NULL,1,3,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-02 00:20:30'),
(6,'disc_execute','Disconnection execution','Executes approved disconnections inside the rule hours, rechecking eligibility under a lock',15,NULL,1,3,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-02 00:20:30'),
(7,'reconnect','Reconnection processing','Requests and executes reconnections of accounts that qualify after payment',5,NULL,1,3,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-02 00:20:30'),
(8,'net_ops','Network operation retries','Sends queued network operations and retries failed ones within their limit',5,NULL,1,3,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-02 00:20:30'),
(9,'net_reconcile','Network reconciliation','Compares the expected subscriber state with the device state',360,NULL,1,3,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-02 00:20:30'),
(10,'temp_recon','Expired temporary reconnections','Disconnects again the temporary reconnections that expired unpaid',60,NULL,1,3,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-02 00:20:30'),
(11,'contracts','Contract expiration notices','Notifies subscribers of contracts ending within 30 days and marks expired ones',1440,9,1,3,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-02 00:20:30'),
(12,'equipment','Equipment maintenance reminders','Lists infrastructure due for maintenance and equipment pending recovery',1440,7,1,3,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-02 00:20:30'),
(13,'ticket_alerts','Overdue support-ticket alerts','Escalates tickets past their SLA deadline',30,NULL,1,3,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-02 00:20:30'),
(14,'daily_summary','Daily financial summary','Writes the day\'s billing and collection totals to the job log',1440,23,1,3,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-02 00:20:30'),
(15,'backup','Database backup','Writes a full database backup to storage/backups',1440,0,1,3,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-02 00:20:30'),
(16,'notify_retry','Notification delivery and retries','Sends queued SMS / e-mail and retries failed ones within their limit',5,NULL,1,3,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-02 00:20:30'),
(17,'arrangements','Payment arrangement follow-up','Marks missed installments and ends defaulted arrangements',1440,3,1,3,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-02 00:20:30');
